    properties: [["Events", "Table", "Required", "Flat occurrences, one row per day an event appears on; a multi-day event is several rows, and an optional SeriesId marks which occurrences belong to the same recurring series"], ["Channels", "Table", "Required", "Category key, title and color used to tint each chip"], ["FocusDate", "DateTime", "Today()", "Which month or week opens first"], ["View", "Text", "month", "month, week or agenda"], ["Config", "Record", "Default", "Row height, chip slots, first day of week, work hours and holiday tinting"], ["TimeZone", "Text", "Blank", "An IANA/Windows zone name Events' dates are displayed in; blank uses the running user's own local zone — for a distributed team, the host converts through Power Apps' own TimeZoneOffset/TimeZoneInformation functions before Events reaches the component"], ["Language", "Text", "Blank", "A BCP-47 tag this component uses to render month and weekday names (\"March 2026\", \"S M T W T F S\") in that language — unlike most Language properties elsewhere in this catalog, this one is used inside the component itself, since month/weekday names are generated here rather than pre-formatted by the host"]],
